=== case_id ===
Case-23-countdown-009

=== 用户原始指令 (query.txt) ===
搞个倒计时 点一下跳app 日历的能读到 还要提醒我快来不及了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个倒计时 点一下跳app 日历的能读到 还要提醒我快来不及了",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日历日程唯一标识符，用于跳转或查看相关日程。",
              "sampleValue": "calendar_demo_001"
            },
            "title": {
              "type": "string",
              "description": "倒计时纪念日或日程标题。",
              "sampleValue": "纪念日"
            },
            "dtStart": {
              "type": "string",
              "description": "日程开始时间或面向倒计时场景的剩余时间展示文本。",
              "sampleValue": "3天"
            },
            "dtEnd": {
              "type": "string",
              "description": "倒计时目标日期或结束时间展示文本。",
              "sampleValue": "7月12日"
            },
            "remindTime": [
              {
                "type": "string",
                "description": "日程提醒时间文本，用于提示用户临近截止。",
                "sampleValue": "明天 09:00 提醒"
              }
            ],
            "importantEventType": {
              "type": "integer",
              "description": "重要日关系类型，2 表示倒数日。",
              "sampleValue": 2
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_schedule2.png",
      "description": "日程图标，适合用于日历事件、纪念日或当下日程的识别入口。"
    },
    {
      "src": "resources/base/media/icon_alarm_clock.png",
      "description": "闹钟图标，适合用于日程提醒、临近截止或倒计时提示。"
    }
  ]
}

